WITH with_last AS (SELECT s.*, top1.account_opened_date, top1.account_status FROM customers s LEFT JOIN LATERAL (SELECT c.opened_date AS account_opened_date, c.status AS account_status FROM accounts c WHERE c.customer_id = s.id AND c.opened_date <= s.signup_date ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), eligible AS (SELECT s.* FROM with_last s WHERE EXISTS (SELECT 1 FROM orders ch WHERE ch.customer_id = s.id AND ch.order_date >= s.signup_date)), eligible_customers AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM subscriptions ch WHERE ch.customer_id = s.id AND ch.end_date < s.signup_date)), cleaned AS (SELECT id, name, city, segment, signup_date, is_active, age, account_opened_date, account_status, REPLACE(name, ' ', '') name_slug FROM eligible_customers WHERE city IS NOT NULL AND email IS NULL), filtered AS (SELECT id, name, signup_date, is_active, age, account_opened_date, name_slug, DATE_FORMAT(account_opened_date, 'MMM yyyy') account_opened_date_label FROM cleaned WHERE signup_date > DATE '2023-07-26'), daily AS (SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, COUNT(*) AS cnt, STDDEV_SAMP(age) AS age_stddev, STDDEV_SAMP(age) AS age_stddev_2 FROM filtered GROUP BY 1) SELECT week_start, cnt, age_stddev, age_stddev_2 FROM daily ORDER BY week_start DESC;
